CREATE OR REPLACE FUNCTION public.tg_receive_scope() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND private.can_receive(auth.uid()) AND NOT private.can_write(auth.uid()) THEN IF (to_jsonb(NEW)-ARRAY['recebida','recebida_em','recebida_por','recebida_por_nome','data_chegada','updated_at','agendamento']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['recebida','recebida_em','recebida_por','recebida_por_nome','data_chegada','updated_at','agendamento']) THEN RAISE EXCEPTION 'Conferente só pode registrar recebimento'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER receive_note_scope BEFORE UPDATE ON public.notas_fiscais FOR EACH ROW EXECUTE FUNCTION public.tg_receive_scope();
CREATE OR REPLACE FUNCTION public.tg_receive_load_scope() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND private.can_receive(auth.uid()) AND NOT private.can_write(auth.uid()) THEN IF (to_jsonb(NEW)-ARRAY['status','data_chegada','recebido_por','recebido_por_nome','obs_recebimento','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','data_chegada','recebido_por','recebido_por_nome','obs_recebimento','updated_at']) OR NEW.status NOT IN ('recebida','recebida_parcial') THEN RAISE EXCEPTION 'Conferente só pode confirmar chegada'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER receive_load_scope BEFORE UPDATE ON public.cargas_entrada FOR EACH ROW EXECUTE FUNCTION public.tg_receive_load_scope();
CREATE OR REPLACE FUNCTION public.tg_financial_lock() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.estado_frete IN ('conferido','pronto_faturamento','faturado') AND (NEW.calculo_id IS DISTINCT FROM OLD.calculo_id OR NEW.nota_fiscal_id IS DISTINCT FROM OLD.nota_fiscal_id OR NEW.fornecedor_id IS DISTINCT FROM OLD.fornecedor_id OR NEW.valor_base IS DISTINCT FROM OLD.valor_base) THEN RAISE EXCEPTION 'Cálculo fechado não pode mudar'; END IF; IF OLD.estado_frete='faturado' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Frete faturado é imutável'; END IF; IF NEW.estado_frete IN ('conferido','pronto_faturamento','faturado') AND NOT EXISTS(SELECT 1 FROM comprovantes WHERE id=NEW.comprovante_id AND status='aprovado' AND tipo_documento='canhoto' AND nota_id=NEW.nota_fiscal_id) THEN RAISE EXCEPTION 'Fechamento exige canhoto aprovado'; END IF; RETURN NEW; END $$;
CREATE TRIGGER financial_lock BEFORE UPDATE ON public.financeiro FOR EACH ROW EXECUTE FUNCTION public.tg_financial_lock();
CREATE OR REPLACE FUNCTION public.tg_document_submission() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT private.can_write(auth.uid()) AND auth.uid() IS NOT NULL THEN NEW.tipo_documento:='nao_identificado';NEW.triagem:='pendente';NEW.reconhecimento:='{}';NEW.observacoes_documento:=''; END IF;RETURN NEW;END $$;
CREATE TRIGGER document_submission BEFORE INSERT ON public.comprovantes FOR EACH ROW EXECUTE FUNCTION public.tg_document_submission();
ALTER TABLE public.notas_fiscais ADD COLUMN tabela_frete_id uuid REFERENCES public.tabelas_frete(id), ADD COLUMN destino_entrega_cidade text, ADD COLUMN destino_entrega_uf text, ADD COLUMN peso_frete numeric;
COMMENT ON COLUMN public.notas_fiscais.peso_frete IS 'Peso operacional autorizado para cálculo; não modifica peso fiscal';
CREATE OR REPLACE FUNCTION public.tg_freight_overrides_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.tabela_frete_id IS DISTINCT FROM OLD.tabela_frete_id OR NEW.destino_entrega_cidade IS DISTINCT FROM OLD.destino_entrega_cidade OR NEW.destino_entrega_uf IS DISTINCT FROM OLD.destino_entrega_uf OR NEW.peso_frete IS DISTINCT FROM OLD.peso_frete THEN IF NOT private.can_finance(auth.uid()) THEN RAISE EXCEPTION 'Ajuste de frete não autorizado'; END IF; IF NEW.peso_frete<0 THEN RAISE EXCEPTION 'Peso inválido';END IF;IF EXISTS(SELECT 1 FROM financeiro WHERE nota_fiscal_id=NEW.id AND estado_frete IN ('conferido','pronto_faturamento','faturado')) THEN RAISE EXCEPTION 'Frete fechado'; END IF; INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('nota',NEW.id,'parametros_frete',jsonb_build_object('anterior',jsonb_build_object('peso',OLD.peso_frete,'cidade',OLD.destino_entrega_cidade,'uf',OLD.destino_entrega_uf,'tabela',OLD.tabela_frete_id),'atual',jsonb_build_object('peso',NEW.peso_frete,'cidade',NEW.destino_entrega_cidade,'uf',NEW.destino_entrega_uf,'tabela',NEW.tabela_frete_id))::text,auth.uid());END IF;RETURN NEW;END $$;
CREATE TRIGGER freight_overrides_audit BEFORE UPDATE ON public.notas_fiscais FOR EACH ROW EXECUTE FUNCTION public.tg_freight_overrides_audit();